values ($school_967_logic$[{"slug":"logical-thinking","course":{"title":"فن التفكير المنطقي","description":"من المقدمات والنتائج إلى الاستنباط والشروط والاستنتاج من الأدلة، عبر 12 محطة تفاعلية.","category":"المنطق والتفكير"},"stages":[{"index":0,"stage":{"title":"الحجة والمقدمة والنتيجة","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم الحجة والمقدمة والنتيجة عبر أمثلة وقواعد قابلة للتطبيق. الحجة مجموعة مقدمات تدعم نتيجة. فالأسباب هي ما نعتمد عليه، والنتيجة ما نحاول إثباته؛ أما الجملة التي لا تسند دعوى إلى دليل فليست حجة كاملة.","tips":["الحجة مجموعة مقدمات تدعم نتيجة. فالأسباب هي ما نعتمد عليه، والنتيجة ما نحاول إثباته؛ أما الجملة التي لا تسند دعوى إلى دليل فليست حجة كاملة.","كل الطيور لها ريش، والعصفور طائر، إذن للعصفور ريش. الجملتان الأوليان مقدمتان والأخيرة نتيجة؛ يمكنك رسم سهم من الأسباب إلى النتيجة.","لا تجعل شهرة المتكلم أو وجود كلمة «إذن» دليلًا على صحة الاستنتاج. اسأل: ما المقدمة وما الذي تدعمه؟"],"lessons":[{"title":"فهم الفكرة الأساسية","body":"الحجة مجموعة مقدمات تدعم نتيجة. فالأسباب هي ما نعتمد عليه، والنتيجة ما نحاول إثباته؛ أما الجملة التي لا تسند دعوى إلى دليل فليست حجة كاملة.","example":"تقديم سبب للنتيجة","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"كل الطيور لها ريش، والعصفور طائر، إذن للعصفور ريش. الجملتان الأوليان مقدمتان والأخيرة نتيجة؛ يمكنك رسم سهم من الأسباب إلى النتيجة.","example":"اقرأ الحجة ← حدد المقدمات ← استخرج النتيجة","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"لا تجعل شهرة المتكلم أو وجود كلمة «إذن» دليلًا على صحة الاستنتاج. اسأل: ما المقدمة وما الذي تدعمه؟ خطوات العمل: اقرأ الحجة ← حدد المقدمات ← استخرج النتيجة. المصطلح الذي تعلمته: النتيجة.","example":"النتيجة","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"ما وظيفة المقدمة؟","target":"","options":["تزيين الجملة","إخفاء الدليل","تكرار العنوان","تقديم سبب للنتيجة"],"answerIndex":3,"explanation":"الحجة مجموعة مقدمات تدعم نتيجة. فالأسباب هي ما نعتمد عليه، والنتيجة ما نحاول إثباته؛ أما الجملة التي لا تسند دعوى إلى دليل فليست حجة كاملة."},{"number":1,"kind":"choice","prompt":"ما النتيجة في مثال العصفور؟","target":"","options":["العصفور طائر","كل الحشرات تطير","للعصفور ريش","كل الطيور لها ريش"],"answerIndex":2,"explanation":"كل الطيور لها ريش، والعصفور طائر، إذن للعصفور ريش. الجملتان الأوليان مقدمتان والأخيرة نتيجة؛ يمكنك رسم سهم من الأسباب إلى النتيجة."},{"number":2,"kind":"choice","prompt":"أي جملة تحتوي على استدلال؟","target":"","options":["الطقس جميل","أمطرت فابتلت الأرض، لذلك قد تكون زلقة","أحب المطر","الأرض خضراء"],"answerIndex":1,"explanation":"الحجة مجموعة مقدمات تدعم نتيجة. فالأسباب هي ما نعتمد عليه، والنتيجة ما نحاول إثباته؛ أما الجملة التي لا تسند دعوى إلى دليل فليست حجة كاملة."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «الحجة والمقدمة والنتيجة»؟","target":"","options":["اقرأ الحجة","حدد المقدمات","استخرج النتيجة","اختيار نتيجة دون دليل"],"answerIndex":0,"explanation":"الحجة مجموعة مقدمات تدعم نتيجة. فالأسباب هي ما نعتمد عليه، والنتيجة ما نحاول إثباته؛ أما الجملة التي لا تسند دعوى إلى دليل فليست حجة كاملة."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «الحجة والمقدمة والنتيجة».","target":"","tokens":["استخرج النتيجة","حدد المقدمات","اقرأ الحجة"],"answer":["اقرأ الحجة","حدد المقدمات","استخرج النتيجة"],"explanation":"الترتيب الصحيح: اقرأ الحجة ← حدد المقدمات ← استخرج النتيجة."},{"number":5,"kind":"type","prompt":"ما اسم الدعوى التي تسندها المقدمات؟","target":"","answer":"النتيجة","explanation":"الحجة مجموعة مقدمات تدعم نتيجة. فالأسباب هي ما نعتمد عليه، والنتيجة ما نحاول إثباته؛ أما الجملة التي لا تسند دعوى إلى دليل فليست حجة كاملة."}]},{"index":1,"stage":{"title":"صلاحية الحجة","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم صلاحية الحجة عبر أمثلة وقواعد قابلة للتطبيق. الاستنتاج الصالح يستحيل معه صدق جميع المقدمات وكذب النتيجة في الوقت نفسه. الصلاحية تتعلق بالشكل المنطقي، وليس بكون المقدمات صحيحة واقعيًا.","tips":["الاستنتاج الصالح يستحيل معه صدق جميع المقدمات وكذب النتيجة في الوقت نفسه. الصلاحية تتعلق بالشكل المنطقي، وليس بكون المقدمات صحيحة واقعيًا.","كل القطط ثدييات؛ لوزة قطة؛ إذن لوزة ثديية. إذا قبلت المقدمتين فلا يمكنك رفض النتيجة. هذا شكل صالح من الاستدلال.","قد تكون نتيجة حجة غير صالحة صحيحة مصادفة؛ وقد تكون حجة ذات شكل صالح مبنية على مقدمات خاطئة. افصل الصلاحية عن صدق الوقائع."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"الاستنتاج الصالح يستحيل معه صدق جميع المقدمات وكذب النتيجة في الوقت نفسه. الصلاحية تتعلق بالشكل المنطقي، وليس بكون المقدمات صحيحة واقعيًا.","example":"إذا استحال صدق المقدمات وكذب النتيجة","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"كل القطط ثدييات؛ لوزة قطة؛ إذن لوزة ثديية. إذا قبلت المقدمتين فلا يمكنك رفض النتيجة. هذا شكل صالح من الاستدلال.","example":"اكتب المقدمات ← افترض صدقها ← افحص لزوم النتيجة","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"قد تكون نتيجة حجة غير صالحة صحيحة مصادفة؛ وقد تكون حجة ذات شكل صالح مبنية على مقدمات خاطئة. افصل الصلاحية عن صدق الوقائع. خطوات العمل: اكتب المقدمات ← افترض صدقها ← افحص لزوم النتيجة. المصطلح الذي تعلمته: الصلاحية.","example":"الصلاحية","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"متى يكون الاستنتاج صالحًا؟","target":"","options":["إذا كان قصيرًا","إذا وافق الجمهور","إذا استحال صدق المقدمات وكذب النتيجة","إذا كان مشهورًا"],"answerIndex":2,"explanation":"الاستنتاج الصالح يستحيل معه صدق جميع المقدمات وكذب النتيجة في الوقت نفسه. الصلاحية تتعلق بالشكل المنطقي، وليس بكون المقدمات صحيحة واقعيًا."},{"number":1,"kind":"choice","prompt":"ما حكم «كل أ ب، س أ، إذن س ب»؟","target":"","options":["يعتمد على اسم س","صالح من حيث البنية","متناقض دائمًا","غير صالح دائمًا"],"answerIndex":1,"explanation":"كل القطط ثدييات؛ لوزة قطة؛ إذن لوزة ثديية. إذا قبلت المقدمتين فلا يمكنك رفض النتيجة. هذا شكل صالح من الاستدلال."},{"number":2,"kind":"choice","prompt":"هل الصلاحية تثبت صدق المقدمات؟","target":"","options":["لا","نعم دائمًا","إذا طالت الحجة","إذا قالها معلم"],"answerIndex":0,"explanation":"الاستنتاج الصالح يستحيل معه صدق جميع المقدمات وكذب النتيجة في الوقت نفسه. الصلاحية تتعلق بالشكل المنطقي، وليس بكون المقدمات صحيحة واقعيًا."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «صلاحية الحجة»؟","target":"","options":["افترض صدقها","افحص لزوم النتيجة","اختيار نتيجة دون دليل","اكتب المقدمات"],"answerIndex":3,"explanation":"الاستنتاج الصالح يستحيل معه صدق جميع المقدمات وكذب النتيجة في الوقت نفسه. الصلاحية تتعلق بالشكل المنطقي، وليس بكون المقدمات صحيحة واقعيًا."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «صلاحية الحجة».","target":"","tokens":["افحص لزوم النتيجة","افترض صدقها","اكتب المقدمات"],"answer":["اكتب المقدمات","افترض صدقها","افحص لزوم النتيجة"],"explanation":"الترتيب الصحيح: اكتب المقدمات ← افترض صدقها ← افحص لزوم النتيجة."},{"number":5,"kind":"type","prompt":"ما اسم خاصية لزوم النتيجة منطقيًا؟","target":"","answer":"الصلاحية","explanation":"الاستنتاج الصالح يستحيل معه صدق جميع المقدمات وكذب النتيجة في الوقت نفسه. الصلاحية تتعلق بالشكل المنطقي، وليس بكون المقدمات صحيحة واقعيًا."}]},{"index":2,"stage":{"title":"كل وبعض ولا أحد","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم كل وبعض ولا أحد عبر أمثلة وقواعد قابلة للتطبيق. «كل» تعني جميع أفراد مجموعة، و«بعض» يعني فردًا على الأقل، و«لا أحد» ينفي وجود أفراد من النوع المحدد. لا تعكس اتجاه علاقة المجموعات دون دليل.","tips":["«كل» تعني جميع أفراد مجموعة، و«بعض» يعني فردًا على الأقل، و«لا أحد» ينفي وجود أفراد من النوع المحدد. لا تعكس اتجاه علاقة المجموعات دون دليل.","كل الورود نباتات؛ هذا لا يجعل جميع النباتات ورودًا. وبعض الحيوانات سريعة؛ هذا لا يضمن وجود قطة سريعة دون معلومات أخرى.","لا تستنتج «كل ب أ» من «كل أ ب». ولا تعتبر «بعض» مساوية لنصف المجموعة أو لأغلبيتها؛ إنها تعني وجود فرد واحد على الأقل."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"«كل» تعني جميع أفراد مجموعة، و«بعض» يعني فردًا على الأقل، و«لا أحد» ينفي وجود أفراد من النوع المحدد. لا تعكس اتجاه علاقة المجموعات دون دليل.","example":"واحدًا على الأقل","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"كل الورود نباتات؛ هذا لا يجعل جميع النباتات ورودًا. وبعض الحيوانات سريعة؛ هذا لا يضمن وجود قطة سريعة دون معلومات أخرى.","example":"حدد المجموعة ← اقرأ أداة الكم ← تحقق من الاتجاه","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"لا تستنتج «كل ب أ» من «كل أ ب». ولا تعتبر «بعض» مساوية لنصف المجموعة أو لأغلبيتها؛ إنها تعني وجود فرد واحد على الأقل. خطوات العمل: حدد المجموعة ← اقرأ أداة الكم ← تحقق من الاتجاه. المصطلح الذي تعلمته: بعض.","example":"بعض","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"ماذا تعني «بعض»؟","target":"","options":["شخصين فقط","واحدًا على الأقل","الأغلبية","النصف بالضبط"],"answerIndex":1,"explanation":"«كل» تعني جميع أفراد مجموعة، و«بعض» يعني فردًا على الأقل، و«لا أحد» ينفي وجود أفراد من النوع المحدد. لا تعكس اتجاه علاقة المجموعات دون دليل."},{"number":1,"kind":"choice","prompt":"ما الذي يلزم من «كل الورود نباتات»؟","target":"","options":["كل وردة نبات","كل نبات وردة","كل النباتات حمراء","لا نباتات أخرى"],"answerIndex":0,"explanation":"كل الورود نباتات؛ هذا لا يجعل جميع النباتات ورودًا. وبعض الحيوانات سريعة؛ هذا لا يضمن وجود قطة سريعة دون معلومات أخرى."},{"number":2,"kind":"choice","prompt":"ماذا تعني «لا طالب غائب»؟","target":"","options":["كل الناس طلاب","بعض الطلاب غائبون","كل الطلاب خارج المدرسة","لا يوجد طالب غائب"],"answerIndex":3,"explanation":"«كل» تعني جميع أفراد مجموعة، و«بعض» يعني فردًا على الأقل، و«لا أحد» ينفي وجود أفراد من النوع المحدد. لا تعكس اتجاه علاقة المجموعات دون دليل."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «كل وبعض ولا أحد»؟","target":"","options":["تحقق من الاتجاه","اختيار نتيجة دون دليل","حدد المجموعة","اقرأ أداة الكم"],"answerIndex":2,"explanation":"«كل» تعني جميع أفراد مجموعة، و«بعض» يعني فردًا على الأقل، و«لا أحد» ينفي وجود أفراد من النوع المحدد. لا تعكس اتجاه علاقة المجموعات دون دليل."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «كل وبعض ولا أحد».","target":"","tokens":["تحقق من الاتجاه","اقرأ أداة الكم","حدد المجموعة"],"answer":["حدد المجموعة","اقرأ أداة الكم","تحقق من الاتجاه"],"explanation":"الترتيب الصحيح: حدد المجموعة ← اقرأ أداة الكم ← تحقق من الاتجاه."},{"number":5,"kind":"type","prompt":"ما كلمة الكم التي تعني فردًا على الأقل؟","target":"","answer":"بعض","explanation":"«كل» تعني جميع أفراد مجموعة، و«بعض» يعني فردًا على الأقل، و«لا أحد» ينفي وجود أفراد من النوع المحدد. لا تعكس اتجاه علاقة المجموعات دون دليل."}]},{"index":3,"stage":{"title":"شرط إذا فإن","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم شرط إذا فإن عبر أمثلة وقواعد قابلة للتطبيق. إذا ثبتت قاعدة «إذا أ فإن ب» وثبت وقوع أ، لزم وقوع ب. لكن وقوع ب وحده لا يعني وقوع أ؛ فقد تكون لب أسباب مختلفة.","tips":["إذا ثبتت قاعدة «إذا أ فإن ب» وثبت وقوع أ، لزم وقوع ب. لكن وقوع ب وحده لا يعني وقوع أ؛ فقد تكون لب أسباب مختلفة.","إذا كان العدد مضاعفًا لأربعة فهو زوجي؛ العدد 12 مضاعف لأربعة، إذن هو زوجي. العدد 6 زوجي لكنه ليس مضاعفًا لأربعة.","الخطأ الشائع «إثبات التالي»: أ يستلزم ب؛ ب حاصل؛ إذن أ حاصل. راجع اتجاه السهم ولا تعكس الشرط."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"إذا ثبتت قاعدة «إذا أ فإن ب» وثبت وقوع أ، لزم وقوع ب. لكن وقوع ب وحده لا يعني وقوع أ؛ فقد تكون لب أسباب مختلفة.","example":"مثال: ب","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"إذا كان العدد مضاعفًا لأربعة فهو زوجي؛ العدد 12 مضاعف لأربعة، إذن هو زوجي. العدد 6 زوجي لكنه ليس مضاعفًا لأربعة.","example":"اقرأ الشرط ← تحقق من المقدم ← استنتج التالي","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"الخطأ الشائع «إثبات التالي»: أ يستلزم ب؛ ب حاصل؛ إذن أ حاصل. راجع اتجاه السهم ولا تعكس الشرط. خطوات العمل: اقرأ الشرط ← تحقق من المقدم ← استنتج التالي. المصطلح الذي تعلمته: التالي.","example":"التالي","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"من «إذا أ فب» مع وقوع أ ماذا نستنتج؟","target":"","options":["ب","ليس ب","ليس أ","لا نتيجة"],"answerIndex":0,"explanation":"إذا ثبتت قاعدة «إذا أ فإن ب» وثبت وقوع أ، لزم وقوع ب. لكن وقوع ب وحده لا يعني وقوع أ؛ فقد تكون لب أسباب مختلفة."},{"number":1,"kind":"choice","prompt":"ما خطأ «العدد زوجي، إذن يقبل القسمة على 4»؟","target":"","options":["تأكيد المقدم","تطبيق قاعدة صحيحة","ذكر مثال مضاد","عكس الشرط دون مبرر"],"answerIndex":3,"explanation":"إذا كان العدد مضاعفًا لأربعة فهو زوجي؛ العدد 12 مضاعف لأربعة، إذن هو زوجي. العدد 6 زوجي لكنه ليس مضاعفًا لأربعة."},{"number":2,"kind":"choice","prompt":"أي عدد زوجي لا يقبل القسمة على أربعة؟","target":"","options":["12","16","6","8"],"answerIndex":2,"explanation":"إذا ثبتت قاعدة «إذا أ فإن ب» وثبت وقوع أ، لزم وقوع ب. لكن وقوع ب وحده لا يعني وقوع أ؛ فقد تكون لب أسباب مختلفة."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «شرط إذا فإن»؟","target":"","options":["اختيار نتيجة دون دليل","اقرأ الشرط","تحقق من المقدم","استنتج التالي"],"answerIndex":1,"explanation":"إذا ثبتت قاعدة «إذا أ فإن ب» وثبت وقوع أ، لزم وقوع ب. لكن وقوع ب وحده لا يعني وقوع أ؛ فقد تكون لب أسباب مختلفة."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «شرط إذا فإن».","target":"","tokens":["استنتج التالي","تحقق من المقدم","اقرأ الشرط"],"answer":["اقرأ الشرط","تحقق من المقدم","استنتج التالي"],"explanation":"الترتيب الصحيح: اقرأ الشرط ← تحقق من المقدم ← استنتج التالي."},{"number":5,"kind":"type","prompt":"ما اسم الجزء بعد «فإن»؟","target":"","answer":"التالي","explanation":"إذا ثبتت قاعدة «إذا أ فإن ب» وثبت وقوع أ، لزم وقوع ب. لكن وقوع ب وحده لا يعني وقوع أ؛ فقد تكون لب أسباب مختلفة."}]},{"index":4,"stage":{"title":"نفي التالي","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم نفي التالي عبر أمثلة وقواعد قابلة للتطبيق. إذا صدق «إذا أ فإن ب» وكان ب غير حاصل، فإن أ غير حاصل. يسمى هذا الاستدلال نفي التالي، وهو شكل صحيح من المقابلة بالنقيض.","tips":["إذا صدق «إذا أ فإن ب» وكان ب غير حاصل، فإن أ غير حاصل. يسمى هذا الاستدلال نفي التالي، وهو شكل صحيح من المقابلة بالنقيض.","إذا كان الشكل مربعًا فهو مستطيل. هذا الشكل ليس مستطيلًا؛ إذن ليس مربعًا. عكس ذلك غير صحيح: قد يكون الشكل مستطيلًا دون أن يكون مربعًا.","لا تخلط نفي التالي بنفي المقدم: عدم حدوث أ لا يكفي لإثبات عدم حدوث ب، لأن ب قد ينتج عن سبب آخر."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"إذا صدق «إذا أ فإن ب» وكان ب غير حاصل، فإن أ غير حاصل. يسمى هذا الاستدلال نفي التالي، وهو شكل صحيح من المقابلة بالنقيض.","example":"ليس أ","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"إذا كان الشكل مربعًا فهو مستطيل. هذا الشكل ليس مستطيلًا؛ إذن ليس مربعًا. عكس ذلك غير صحيح: قد يكون الشكل مستطيلًا دون أن يكون مربعًا.","example":"اكتب الشرط ← انف التالي ← استنتج نفي المقدم","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"لا تخلط نفي التالي بنفي المقدم: عدم حدوث أ لا يكفي لإثبات عدم حدوث ب، لأن ب قد ينتج عن سبب آخر. خطوات العمل: اكتب الشرط ← انف التالي ← استنتج نفي المقدم. المصطلح الذي تعلمته: نفي التالي.","example":"نفي التالي","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"من «إذا أ فب» و«ليس ب» ماذا يلزم؟","target":"","options":["أ","ب","أ أو ب","ليس أ"],"answerIndex":3,"explanation":"إذا صدق «إذا أ فإن ب» وكان ب غير حاصل، فإن أ غير حاصل. يسمى هذا الاستدلال نفي التالي، وهو شكل صحيح من المقابلة بالنقيض."},{"number":1,"kind":"choice","prompt":"الشكل ليس مستطيلًا، هل يمكن أن يكون مربعًا؟","target":"","options":["نعلم أنه مثلث","لا نتيجة","لا","نعم"],"answerIndex":2,"explanation":"إذا كان الشكل مربعًا فهو مستطيل. هذا الشكل ليس مستطيلًا؛ إذن ليس مربعًا. عكس ذلك غير صحيح: قد يكون الشكل مستطيلًا دون أن يكون مربعًا."},{"number":2,"kind":"choice","prompt":"هل «إذا ب فأ» تعادل «إذا أ فب»؟","target":"","options":["عندما نفي الاثنين","لا عمومًا","نعم دائمًا","فقط مع الأرقام"],"answerIndex":1,"explanation":"إذا صدق «إذا أ فإن ب» وكان ب غير حاصل، فإن أ غير حاصل. يسمى هذا الاستدلال نفي التالي، وهو شكل صحيح من المقابلة بالنقيض."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «نفي التالي»؟","target":"","options":["اكتب الشرط","انف التالي","استنتج نفي المقدم","اختيار نتيجة دون دليل"],"answerIndex":0,"explanation":"إذا صدق «إذا أ فإن ب» وكان ب غير حاصل، فإن أ غير حاصل. يسمى هذا الاستدلال نفي التالي، وهو شكل صحيح من المقابلة بالنقيض."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «نفي التالي».","target":"","tokens":["استنتج نفي المقدم","انف التالي","اكتب الشرط"],"answer":["اكتب الشرط","انف التالي","استنتج نفي المقدم"],"explanation":"الترتيب الصحيح: اكتب الشرط ← انف التالي ← استنتج نفي المقدم."},{"number":5,"kind":"type","prompt":"ما اسم الاستدلال الذي يبدأ بنفي التالي؟","target":"","answer":"نفي التالي","explanation":"إذا صدق «إذا أ فإن ب» وكان ب غير حاصل، فإن أ غير حاصل. يسمى هذا الاستدلال نفي التالي، وهو شكل صحيح من المقابلة بالنقيض."}]},{"index":5,"stage":{"title":"الضروري والكافي","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم الضروري والكافي عبر أمثلة وقواعد قابلة للتطبيق. الشرط الكافي يضمن النتيجة إذا تحقق. الشرط الضروري يلزم وجوده لوقوع النتيجة، لكنه قد لا يضمنها وحده. في «إذا أ فب» أ كافٍ لب، وب ضروري لأ.","tips":["الشرط الكافي يضمن النتيجة إذا تحقق. الشرط الضروري يلزم وجوده لوقوع النتيجة، لكنه قد لا يضمنها وحده. في «إذا أ فب» أ كافٍ لب، وب ضروري لأ.","المربع مستطيل بالضرورة، لذلك كون الشكل مربعًا كافٍ لكونه مستطيلًا، وكونه مستطيلًا ضروري لكونه مربعًا؛ لكن ليس كل مستطيل مربعًا.","انظر لاتجاه الاستلزام عند وصف الشرط: لا تجعل ما يلزم للحصول على شيء كافيًا لضمانه، ولا تعكس العلاقة دون دليل."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"الشرط الكافي يضمن النتيجة إذا تحقق. الشرط الضروري يلزم وجوده لوقوع النتيجة، لكنه قد لا يضمنها وحده. في «إذا أ فب» أ كافٍ لب، وب ضروري لأ.","example":"أن يكون مربعًا","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"المربع مستطيل بالضرورة، لذلك كون الشكل مربعًا كافٍ لكونه مستطيلًا، وكونه مستطيلًا ضروري لكونه مربعًا؛ لكن ليس كل مستطيل مربعًا.","example":"عرّف النتيجة ← حدد ما يكفيها ← حدد ما يلزمها","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"انظر لاتجاه الاستلزام عند وصف الشرط: لا تجعل ما يلزم للحصول على شيء كافيًا لضمانه، ولا تعكس العلاقة دون دليل. خطوات العمل: عرّف النتيجة ← حدد ما يكفيها ← حدد ما يلزمها. المصطلح الذي تعلمته: الكافي.","example":"الكافي","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"ما الشرط الكافي لكون الشكل مستطيلًا؟","target":"","options":["أن يكون كبيرًا","أن يكون مثلثًا","أن يكون مربعًا","أن يكون أحمر"],"answerIndex":2,"explanation":"الشرط الكافي يضمن النتيجة إذا تحقق. الشرط الضروري يلزم وجوده لوقوع النتيجة، لكنه قد لا يضمنها وحده. في «إذا أ فب» أ كافٍ لب، وب ضروري لأ."},{"number":1,"kind":"choice","prompt":"ما الضروري لكونه مربعًا؟","target":"","options":["أن تكون له ثلاث زوايا","أن يكون مستطيلًا","أن يكون ملونًا","أن يكون صغيرًا"],"answerIndex":1,"explanation":"المربع مستطيل بالضرورة، لذلك كون الشكل مربعًا كافٍ لكونه مستطيلًا، وكونه مستطيلًا ضروري لكونه مربعًا؛ لكن ليس كل مستطيل مربعًا."},{"number":2,"kind":"choice","prompt":"هل الضروري يكفي دائمًا؟","target":"","options":["لا","نعم","مع الأسماء","إذا كانت الصورة واضحة"],"answerIndex":0,"explanation":"الشرط الكافي يضمن النتيجة إذا تحقق. الشرط الضروري يلزم وجوده لوقوع النتيجة، لكنه قد لا يضمنها وحده. في «إذا أ فب» أ كافٍ لب، وب ضروري لأ."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «الضروري والكافي»؟","target":"","options":["حدد ما يكفيها","حدد ما يلزمها","اختيار نتيجة دون دليل","عرّف النتيجة"],"answerIndex":3,"explanation":"الشرط الكافي يضمن النتيجة إذا تحقق. الشرط الضروري يلزم وجوده لوقوع النتيجة، لكنه قد لا يضمنها وحده. في «إذا أ فب» أ كافٍ لب، وب ضروري لأ."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «الضروري والكافي».","target":"","tokens":["حدد ما يلزمها","حدد ما يكفيها","عرّف النتيجة"],"answer":["عرّف النتيجة","حدد ما يكفيها","حدد ما يلزمها"],"explanation":"الترتيب الصحيح: عرّف النتيجة ← حدد ما يكفيها ← حدد ما يلزمها."},{"number":5,"kind":"type","prompt":"ما اسم الشرط الذي يضمن النتيجة؟","target":"","answer":"الكافي","explanation":"الشرط الكافي يضمن النتيجة إذا تحقق. الشرط الضروري يلزم وجوده لوقوع النتيجة، لكنه قد لا يضمنها وحده. في «إذا أ فب» أ كافٍ لب، وب ضروري لأ."}]},{"index":6,"stage":{"title":"و أو ليس","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم و أو ليس عبر أمثلة وقواعد قابلة للتطبيق. «أ و ب» تصدق إذا صدقت القضيتان معًا. «أ أو ب» الشاملة تصدق إذا صدقت واحدة على الأقل، حتى لو صدقت الاثنتان. «ليس أ» تعكس قيمة صدق أ.","tips":["«أ و ب» تصدق إذا صدقت القضيتان معًا. «أ أو ب» الشاملة تصدق إذا صدقت واحدة على الأقل، حتى لو صدقت الاثنتان. «ليس أ» تعكس قيمة صدق أ.","عندما أ صحيحة وب خاطئة، تكون «أ و ب» خاطئة، و«أ أو ب» صحيحة، و«ليس أ» خاطئة. يمكنك كتابة النتائج في جدول.","الكلمة «أو» قد تستخدم يوميًا على معنى حصري، أما معناها هنا فشامل. لا تخلط بين الاثنين في حل جداول القضايا."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"«أ و ب» تصدق إذا صدقت القضيتان معًا. «أ أو ب» الشاملة تصدق إذا صدقت واحدة على الأقل، حتى لو صدقت الاثنتان. «ليس أ» تعكس قيمة صدق أ.","example":"عندما تصدق الاثنتان","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"عندما أ صحيحة وب خاطئة، تكون «أ و ب» خاطئة، و«أ أو ب» صحيحة، و«ليس أ» خاطئة. يمكنك كتابة النتائج في جدول.","example":"حدد القيم ← طبق الرابط ← اكتب الناتج","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"الكلمة «أو» قد تستخدم يوميًا على معنى حصري، أما معناها هنا فشامل. لا تخلط بين الاثنين في حل جداول القضايا. خطوات العمل: حدد القيم ← طبق الرابط ← اكتب الناتج. المصطلح الذي تعلمته: و.","example":"مثال: و","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"متى تصدق أ و ب؟","target":"","options":["عندما تكذبان","عندما تصدق الاثنتان","مع أ فقط","مع ب فقط"],"answerIndex":1,"explanation":"«أ و ب» تصدق إذا صدقت القضيتان معًا. «أ أو ب» الشاملة تصدق إذا صدقت واحدة على الأقل، حتى لو صدقت الاثنتان. «ليس أ» تعكس قيمة صدق أ."},{"number":1,"kind":"choice","prompt":"عندما أ صحيحة وب خاطئة، ماذا عن أ أو ب؟","target":"","options":["صحيحة","خاطئة","مجهولة","تساوي ليس أ"],"answerIndex":0,"explanation":"عندما أ صحيحة وب خاطئة، تكون «أ و ب» خاطئة، و«أ أو ب» صحيحة، و«ليس أ» خاطئة. يمكنك كتابة النتائج في جدول."},{"number":2,"kind":"choice","prompt":"ما عمل «ليس»؟","target":"","options":["جمع القضيتين","حذف القضايا","إعطاء الصدق دائمًا","قلب قيمة الصدق"],"answerIndex":3,"explanation":"«أ و ب» تصدق إذا صدقت القضيتان معًا. «أ أو ب» الشاملة تصدق إذا صدقت واحدة على الأقل، حتى لو صدقت الاثنتان. «ليس أ» تعكس قيمة صدق أ."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «و أو ليس»؟","target":"","options":["اكتب الناتج","اختيار نتيجة دون دليل","حدد القيم","طبق الرابط"],"answerIndex":2,"explanation":"«أ و ب» تصدق إذا صدقت القضيتان معًا. «أ أو ب» الشاملة تصدق إذا صدقت واحدة على الأقل، حتى لو صدقت الاثنتان. «ليس أ» تعكس قيمة صدق أ."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «و أو ليس».","target":"","tokens":["اكتب الناتج","طبق الرابط","حدد القيم"],"answer":["حدد القيم","طبق الرابط","اكتب الناتج"],"explanation":"الترتيب الصحيح: حدد القيم ← طبق الرابط ← اكتب الناتج."},{"number":5,"kind":"type","prompt":"ما الرابط الذي يحتاج صدق القضيتين؟","target":"","answer":"و","explanation":"«أ و ب» تصدق إذا صدقت القضيتان معًا. «أ أو ب» الشاملة تصدق إذا صدقت واحدة على الأقل، حتى لو صدقت الاثنتان. «ليس أ» تعكس قيمة صدق أ."}]},{"index":7,"stage":{"title":"التناقض والاتساق","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم التناقض والاتساق عبر أمثلة وقواعد قابلة للتطبيق. القضية ونفيها لا يمكن أن تصدقا معًا في الوقت والسياق والمعنى نفسهما. لكن اختلاف الزمن أو الموضوع أو المقصود قد يزيل التعارض الظاهري.","tips":["القضية ونفيها لا يمكن أن تصدقا معًا في الوقت والسياق والمعنى نفسهما. لكن اختلاف الزمن أو الموضوع أو المقصود قد يزيل التعارض الظاهري.","المكتبة مفتوحة الآن والمكتبة ليست مفتوحة الآن تناقض في الظروف نفسها. أما كانت مفتوحة أمس وهي مغلقة اليوم فليس تناقضًا.","لا تصف اختلاف الآراء بالتناقض الصريح تلقائيًا. حدد هل يتحدث الطرفان عن الأمر نفسه وبالمعنى نفسه والزمن نفسه."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"القضية ونفيها لا يمكن أن تصدقا معًا في الوقت والسياق والمعنى نفسهما. لكن اختلاف الزمن أو الموضوع أو المقصود قد يزيل التعارض الظاهري.","example":"أ وليس أ في السياق نفسه","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"المكتبة مفتوحة الآن والمكتبة ليست مفتوحة الآن تناقض في الظروف نفسها. أما كانت مفتوحة أمس وهي مغلقة اليوم فليس تناقضًا.","example":"ثبت الموضوع ← ثبت الزمن ← قارن الإثبات والنفي","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"لا تصف اختلاف الآراء بالتناقض الصريح تلقائيًا. حدد هل يتحدث الطرفان عن الأمر نفسه وبالمعنى نفسه والزمن نفسه. خطوات العمل: ثبت الموضوع ← ثبت الزمن ← قارن الإثبات والنفي. المصطلح الذي تعلمته: التناقض.","example":"التناقض","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"أي عبارتين متناقضتان؟","target":"","options":["أ وليس أ في السياق نفسه","أ وب","أ أو ب","إذا أ فإن ب"],"answerIndex":0,"explanation":"القضية ونفيها لا يمكن أن تصدقا معًا في الوقت والسياق والمعنى نفسهما. لكن اختلاف الزمن أو الموضوع أو المقصود قد يزيل التعارض الظاهري."},{"number":1,"kind":"choice","prompt":"هل فتح أمس وإغلاق اليوم تناقض؟","target":"","options":["نعم دائمًا","إذا كانت المكتبة كبيرة","إذا كان الموظف مختلفًا","لا لاختلاف الزمن"],"answerIndex":3,"explanation":"المكتبة مفتوحة الآن والمكتبة ليست مفتوحة الآن تناقض في الظروف نفسها. أما كانت مفتوحة أمس وهي مغلقة اليوم فليس تناقضًا."},{"number":2,"kind":"choice","prompt":"لماذا نفحص السياق؟","target":"","options":["لإلغاء النفي","لأن الزمن يثبت الحقيقة","لأن اختلاف المعنى قد يزيل التناقض","لزيادة عدد الكلمات"],"answerIndex":2,"explanation":"القضية ونفيها لا يمكن أن تصدقا معًا في الوقت والسياق والمعنى نفسهما. لكن اختلاف الزمن أو الموضوع أو المقصود قد يزيل التعارض الظاهري."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «التناقض والاتساق»؟","target":"","options":["اختيار نتيجة دون دليل","ثبت الموضوع","ثبت الزمن","قارن الإثبات والنفي"],"answerIndex":1,"explanation":"القضية ونفيها لا يمكن أن تصدقا معًا في الوقت والسياق والمعنى نفسهما. لكن اختلاف الزمن أو الموضوع أو المقصود قد يزيل التعارض الظاهري."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «التناقض والاتساق».","target":"","tokens":["قارن الإثبات والنفي","ثبت الزمن","ثبت الموضوع"],"answer":["ثبت الموضوع","ثبت الزمن","قارن الإثبات والنفي"],"explanation":"الترتيب الصحيح: ثبت الموضوع ← ثبت الزمن ← قارن الإثبات والنفي."},{"number":5,"kind":"type","prompt":"ما اسم امتناع صدق أ ونفي أ معًا؟","target":"","answer":"التناقض","explanation":"القضية ونفيها لا يمكن أن تصدقا معًا في الوقت والسياق والمعنى نفسهما. لكن اختلاف الزمن أو الموضوع أو المقصود قد يزيل التعارض الظاهري."}]},{"index":8,"stage":{"title":"الاستنباط والاستقراء","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم الاستنباط والاستقراء عبر أمثلة وقواعد قابلة للتطبيق. الاستنباط يستخرج نتيجة لازمة من مقدمات مفترضة؛ أما الاستقراء فيعمم من مشاهدات محدودة، فيكون غالبًا قابلًا للمراجعة. التكرار لا يحوّل تعميمًا إلى يقين منطقي.","tips":["الاستنباط يستخرج نتيجة لازمة من مقدمات مفترضة؛ أما الاستقراء فيعمم من مشاهدات محدودة، فيكون غالبًا قابلًا للمراجعة. التكرار لا يحوّل تعميمًا إلى يقين منطقي.","إذا كانت كل كتب الرف حمراء وهذا كتاب على الرف فاستنتاج لونه استنباط. رؤية عشرة كتب حمراء ثم الجزم بلون جميع كتب المكتبة استقراء غير يقيني.","قيّم تمثيل العينة وعددها بدل تعميم النتيجة من عدد صغير أو عينة منحازة، ولا تساو بين احتمال قوي ويقين مطلق."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"الاستنباط يستخرج نتيجة لازمة من مقدمات مفترضة؛ أما الاستقراء فيعمم من مشاهدات محدودة، فيكون غالبًا قابلًا للمراجعة. التكرار لا يحوّل تعميمًا إلى يقين منطقي.","example":"الاستنباط","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"إذا كانت كل كتب الرف حمراء وهذا كتاب على الرف فاستنتاج لونه استنباط. رؤية عشرة كتب حمراء ثم الجزم بلون جميع كتب المكتبة استقراء غير يقيني.","example":"اجمع الملاحظات ← افحص تمثيل العينة ← صغ تعميمًا قابلًا للمراجعة","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"قيّم تمثيل العينة وعددها بدل تعميم النتيجة من عدد صغير أو عينة منحازة، ولا تساو بين احتمال قوي ويقين مطلق. خطوات العمل: اجمع الملاحظات ← افحص تمثيل العينة ← صغ تعميمًا قابلًا للمراجعة. المصطلح الذي تعلمته: الاستقراء.","example":"الاستقراء","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"ما الاستدلال الذي يستخدم قاعدة تلزم عنها نتيجة؟","target":"","options":["الاستقراء وحده","المصادفة","التكرار العشوائي","الاستنباط"],"answerIndex":3,"explanation":"الاستنباط يستخرج نتيجة لازمة من مقدمات مفترضة؛ أما الاستقراء فيعمم من مشاهدات محدودة، فيكون غالبًا قابلًا للمراجعة. التكرار لا يحوّل تعميمًا إلى يقين منطقي."},{"number":1,"kind":"choice","prompt":"ما طبيعة تعميم من عشر مشاهدات؟","target":"","options":["تناقض","معلومة بلا شروط","استقرائي قابل للمراجعة","يقيني دائمًا"],"answerIndex":2,"explanation":"إذا كانت كل كتب الرف حمراء وهذا كتاب على الرف فاستنتاج لونه استنباط. رؤية عشرة كتب حمراء ثم الجزم بلون جميع كتب المكتبة استقراء غير يقيني."},{"number":2,"kind":"choice","prompt":"كيف تقوي الاستقراء؟","target":"","options":["بتكرار رأي واحد","بعينة كافية وممثلة","بعينة من شخص واحد","بحذف الحالات المخالفة"],"answerIndex":1,"explanation":"الاستنباط يستخرج نتيجة لازمة من مقدمات مفترضة؛ أما الاستقراء فيعمم من مشاهدات محدودة، فيكون غالبًا قابلًا للمراجعة. التكرار لا يحوّل تعميمًا إلى يقين منطقي."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «الاستنباط والاستقراء»؟","target":"","options":["اجمع الملاحظات","افحص تمثيل العينة","صغ تعميمًا قابلًا للمراجعة","اختيار نتيجة دون دليل"],"answerIndex":0,"explanation":"الاستنباط يستخرج نتيجة لازمة من مقدمات مفترضة؛ أما الاستقراء فيعمم من مشاهدات محدودة، فيكون غالبًا قابلًا للمراجعة. التكرار لا يحوّل تعميمًا إلى يقين منطقي."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «الاستنباط والاستقراء».","target":"","tokens":["صغ تعميمًا قابلًا للمراجعة","افحص تمثيل العينة","اجمع الملاحظات"],"answer":["اجمع الملاحظات","افحص تمثيل العينة","صغ تعميمًا قابلًا للمراجعة"],"explanation":"الترتيب الصحيح: اجمع الملاحظات ← افحص تمثيل العينة ← صغ تعميمًا قابلًا للمراجعة."},{"number":5,"kind":"type","prompt":"ما الاستدلال الذي يعمم من أمثلة؟","target":"","answer":"الاستقراء","explanation":"الاستنباط يستخرج نتيجة لازمة من مقدمات مفترضة؛ أما الاستقراء فيعمم من مشاهدات محدودة، فيكون غالبًا قابلًا للمراجعة. التكرار لا يحوّل تعميمًا إلى يقين منطقي."}]},{"index":9,"stage":{"title":"المثال المضاد","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم المثال المضاد عبر أمثلة وقواعد قابلة للتطبيق. مثال مضاد واحد حقيقي يكفي لنقض دعوى كلية من نوع «كل أ ب». يجب أن ينتمي للمجموعة المدعاة ويخالف الوصف المنسوب لجميع أفرادها.","tips":["مثال مضاد واحد حقيقي يكفي لنقض دعوى كلية من نوع «كل أ ب». يجب أن ينتمي للمجموعة المدعاة ويخالف الوصف المنسوب لجميع أفرادها.","«كل الطيور تطير» دعوى غير صحيحة لأن النعامة والبطريق طائران لا يطيران. لكن ذلك لا ينقض دعوى مختلفة مثل «معظم الطيور تطير».","لا تستخدم مثالًا خارج المجموعة، ولا تحاول نقض ادعاء عن أغلبية بمثال واحد دون إحصاءات؛ المطلوب فهم كمّية الدعوى."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"مثال مضاد واحد حقيقي يكفي لنقض دعوى كلية من نوع «كل أ ب». يجب أن ينتمي للمجموعة المدعاة ويخالف الوصف المنسوب لجميع أفرادها.","example":"النعامة","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"«كل الطيور تطير» دعوى غير صحيحة لأن النعامة والبطريق طائران لا يطيران. لكن ذلك لا ينقض دعوى مختلفة مثل «معظم الطيور تطير».","example":"حدد الدعوى الكلية ← ابحث عن فرد منها ← اختبر مخالفة الوصف","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"لا تستخدم مثالًا خارج المجموعة، ولا تحاول نقض ادعاء عن أغلبية بمثال واحد دون إحصاءات؛ المطلوب فهم كمّية الدعوى. خطوات العمل: حدد الدعوى الكلية ← ابحث عن فرد منها ← اختبر مخالفة الوصف. المصطلح الذي تعلمته: المثال المضاد.","example":"المثال المضاد","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"ما مثال مضاد لـ«كل الطيور تطير»؟","target":"","options":["العصفور","النحلة","النعامة","الحمامة"],"answerIndex":2,"explanation":"مثال مضاد واحد حقيقي يكفي لنقض دعوى كلية من نوع «كل أ ب». يجب أن ينتمي للمجموعة المدعاة ويخالف الوصف المنسوب لجميع أفرادها."},{"number":1,"kind":"choice","prompt":"هل مثال واحد ينقض «معظم الطيور تطير»؟","target":"","options":["إذا كان كبيرًا","ليس بالضرورة","نعم","كل ادعاءات الأغلبية كلية"],"answerIndex":1,"explanation":"«كل الطيور تطير» دعوى غير صحيحة لأن النعامة والبطريق طائران لا يطيران. لكن ذلك لا ينقض دعوى مختلفة مثل «معظم الطيور تطير»."},{"number":2,"kind":"choice","prompt":"ما شرط المثال المضاد؟","target":"","options":["عنصر من المجموعة يخالف الوصف","أي عنصر من خارج المجموعة","مثال يؤيد القاعدة","رأي مشهور"],"answerIndex":0,"explanation":"مثال مضاد واحد حقيقي يكفي لنقض دعوى كلية من نوع «كل أ ب». يجب أن ينتمي للمجموعة المدعاة ويخالف الوصف المنسوب لجميع أفرادها."},{"number":3,"kind":"choice","prompt":"ما أول خطوة صحيحة عند تطبيق «المثال المضاد»؟","target":"","options":["ابحث عن فرد منها","اختبر مخالفة الوصف","اختيار نتيجة دون دليل","حدد الدعوى الكلية"],"answerIndex":3,"explanation":"مثال مضاد واحد حقيقي يكفي لنقض دعوى كلية من نوع «كل أ ب». يجب أن ينتمي للمجموعة المدعاة ويخالف الوصف المنسوب لجميع أفرادها."},{"number":4,"kind":"order","prompt":"رتّب خطوات تطبيق «المثال المضاد».","target":"","tokens":["اختبر مخالفة الوصف","ابحث عن فرد منها","حدد الدعوى الكلية"],"answer":["حدد الدعوى الكلية","ابحث عن فرد منها","اختبر مخالفة الوصف"],"explanation":"الترتيب الصحيح: حدد الدعوى الكلية ← ابحث عن فرد منها ← اختبر مخالفة الوصف."},{"number":5,"kind":"type","prompt":"ما اسم ما ينقض التعميم الكلي؟","target":"","answer":"المثال المضاد","explanation":"مثال مضاد واحد حقيقي يكفي لنقض دعوى كلية من نوع «كل أ ب». يجب أن ينتمي للمجموعة المدعاة ويخالف الوصف المنسوب لجميع أفرادها."}]},{"index":10,"stage":{"title":"الارتباط والسببية","subtitle":"تعلم القاعدة ثم اختبر الاستنتاج","intro":"في هذه المحطة نتعلم الارتباط والسببية عبر أمثلة وقواعد قابلة للتطبيق. ظهور متغيرين مترافقين في البيانات يسمى ارتباطًا، ولا يعني بالضرورة أن أحدهما سبب الآخر. ربما توجد عوامل مشتركة أو علاقة معكوسة أو مصادفة.","tips":["ظهور متغيرين مترافقين في البيانات يسمى ارتباطًا، ولا يعني بالضرورة أن أحدهما سبب الآخر. ربما توجد عوامل مشتركة أو علاقة معكوسة أو مصادفة.","قد ترتفع مبيعات المثلجات وحالات السباحة في أيام الحر؛ الحرارة عامل مشترك محتمل. ليس شراء المثلجات دليلًا على أنها تسبّب السباحة.","لا تجعل التتابع الزمني وحده دليل السببية. ابحث عن آلية ممكنة، وراقب ترتيب الأحداث، وقارن مع الحالات الأخرى واضبط العوامل المختلفة."],"lessons":[{"title":"فهم الفكرة الأساسية","body":"ظهور متغيرين مترافقين في البيانات يسمى ارتباطًا، ولا يعني بالضرورة أن أحدهما سبب الآخر. ربما توجد عوامل مشتركة أو علاقة معكوسة أو مصادفة.","example":"تغيّر متغيرين معًا","note":"ابدأ بفهم تعريف الفكرة قبل حفظ المصطلح."},{"title":"مثال محلول خطوة بخطوة","body":"قد ترتفع مبيعات المثلجات وحالات السباحة في أيام الحر؛ الحرارة عامل مشترك محتمل. ليس شراء المثلجات دليلًا على أنها تسبّب السباحة.","example":"لاحظ العلاقة ← ابحث عن عوامل ثالثة ← افحص الدليل السببي","note":"انتبه إلى المعطيات التي تسند هذه الخطوات."},{"title":"الأخطاء الشائعة","body":"لا تجعل التتابع الزمني وحده دليل السببية. ابحث عن آلية ممكنة، وراقب ترتيب الأحداث، وقارن مع الحالات الأخرى واضبط العوامل المختلفة. خطوات العمل: لاحظ العلاقة ← ابحث عن عوامل ثالثة ← افحص الدليل السببي. المصطلح الذي تعلمته: الارتباط.","example":"الارتباط","note":"راجع ما يجوز استنتاجه وما لا تسنده المعلومات."}]},"questions":[{"number":0,"kind":"choice","prompt":"ماذا يثبت الارتباط وحده؟","target":"","options":["انتفاء الصدفة","تغيّر متغيرين معًا","السببية دائمًا","سببًا واحدًا معروفًا"],"answerIndex":1,"explanation":"ظهور م