ثم نفيه، أي NAND(A,B)=NOT(AND(A,B)). لذلك تعطي صفرًا فقط عندما يكون المدخلان 1، وفي بقية الحالات تعطي 1.","إذا A=1 وB=0 فإن AND تساوي 0 وNAND تساوي 1. أما عندما A=B=1 فإن AND تساوي 1 وNAND تساوي 0.","انتبه ألا تخلط NAND مع NOR؛ الأولى تنفي اجتماع الشرطين، والثانية تنفي وجود أي شرط متحقق."],"lessons":[{"title":"كيف تعمل هذه البوابة؟","body":"NAND هي ناتج AND ثم نفيه، أي NAND(A,B)=NOT(AND(A,B)). لذلك تعطي صفرًا فقط عندما يكون المدخلان 1، وفي بقية الحالات تعطي 1.","example":"مثال: 0","note":"اقرأ المدخلات والناتج في جميع الحالات حتى تستوعب وظيفة البوابة."},{"title":"مثال محلول على الصفر والواحد","body":"إذا A=1 وB=0 فإن AND تساوي 0 وNAND تساوي 1. أما عندما A=B=1 فإن AND تساوي 1 وNAND تساوي 0.","example":"احسب AND ← اعكس الناتج ← اكتب NAND","note":"غيّر القيم في المختبر ولاحظ الفرق بين النتيجة والتوقع."},{"title":"خطأ شائع وكيف تتجنبه","body":"انتبه ألا تخلط NAND مع NOR؛ الأولى تنفي اجتماع الشرطين، والثانية تنفي وجود أي شرط متحقق. خطوات الحل: احسب AND ← اعكس الناتج ← اكتب NAND. تذكّر المصطلح أو الناتج: 1.","example":"مثال: 1","note":"الاختبار يقيس ناتج الدائرة، وليس حفظ اسمها فقط."}],"lab":{"kind":"gates","gate":"NAND"}},"questions":[{"number":0,"kind":"choice","prompt":"ما NAND(1,1)؟","target":"","options":["1","2","غير معروف","0"],"answerIndex":3,"explanation":"NAND هي ناتج AND ثم نفيه، أي NAND(A,B)=NOT(AND(A,B)). لذلك تعطي صفرًا فقط عندما يكون المدخلان 1، وفي بقية الحالات تعطي 1."},{"number":1,"kind":"choice","prompt":"ما NAND(1,0)؟","target":"","options":["2","يعتمد على المدخل الثالث","1","0"],"answerIndex":2,"explanation":"إذا A=1 وB=0 فإن AND تساوي 0 وNAND تساوي 1. أما عندما A=B=1 فإن AND تساوي 1 وNAND تساوي 0."},{"number":2,"kind":"choice","prompt":"هل NAND تعادل NOT بعد AND؟","target":"","options":["تعادل NOT وحدها","نعم","لا","تعادل OR دائمًا"],"answerIndex":1,"explanation":"NAND هي ناتج AND ثم نفيه، أي NAND(A,B)=NOT(AND(A,B)). لذلك تعطي صفرًا فقط عندما يكون المدخلان 1، وفي بقية الحالات تعطي 1."},{"number":3,"kind":"choice","prompt":"ما أول خطوة في تمرين «بوابة NAND: نفي AND»؟","target":"","options":["احسب AND","اعكس الناتج","اكتب NAND","اختر نتيجة عشوائية"],"answerIndex":0,"explanation":"NAND هي ناتج AND ثم نفيه، أي NAND(A,B)=NOT(AND(A,B)). لذلك تعطي صفرًا فقط عندما يكون المدخلان 1، وفي بقية الحالات تعطي 1."},{"number":4,"kind":"order","prompt":"رتّب خطوات تمرين «بوابة NAND: نفي AND».","target":"","tokens":["اكتب NAND","اعكس الناتج","احسب AND"],"answer":["احسب AND","اعكس الناتج","اكتب NAND"],"explanation":"الترتيب الصحيح: احسب AND ← اعكس الناتج ← اكتب NAND."},{"number":5,"kind":"type","prompt":"ما ناتج NAND(0,0)؟","target":"","answer":"1","explanation":"NAND هي ناتج AND ثم نفيه، أي NAND(A,B)=NOT(AND(A,B)). لذلك تعطي صفرًا فقط عندما يكون المدخلان 1، وفي بقية الحالات تعطي 1."}]},{"index":5,"stage":{"title":"بوابة NOR: نفي OR","subtitle":"اختر المدخلات وشاهد النتيجة مباشرة","intro":"في هذه المحطة نتعلم بوابة NOR: نفي OR بوساطة جدول الحقيقة والمحاكاة الحية. NOR هي ناتج OR ثم نفيه: NOR(A,B)=NOT(OR(A,B)). تخرج 1 فقط عندما يكون كلا المدخلين 0، وتخرج 0 إذا دخلت قيمة 1 على أي منهما.","tips":["NOR هي ناتج OR ثم نفيه: NOR(A,B)=NOT(OR(A,B)). تخرج 1 فقط عندما يكون كلا المدخلين 0، وتخرج 0 إذا دخلت قيمة 1 على أي منهما.","إذا كان A=0 وB=0 فإن OR تساوي 0 وNOR تساوي 1. أما إذا A=1 فإن NOR تساوي 0 بصرف النظر عن المدخل الثاني.","لا تعتبر NOR مرادفة NAND؛ جرّب المدخلين 00 وستجد NAND=1 وNOR=1، لكن في 01 تختلفان."],"lessons":[{"title":"كيف تعمل هذه البوابة؟","body":"NOR هي ناتج OR ثم نفيه: NOR(A,B)=NOT(OR(A,B)). تخرج 1 فقط عندما يكون كلا المدخلين 0، وتخرج 0 إذا دخلت قيمة 1 على أي منهما.","example":"مثال: 1","note":"اقرأ المدخلات والناتج في جميع الحالات حتى تستوعب وظيفة البوابة."},{"title":"مثال محلول على الصفر والواحد","body":"إذا كان A=0 وB=0 فإن OR تساوي 0 وNOR تساوي 1. أما إذا A=1 فإن NOR تساوي 0 بصرف النظر عن المدخل الثاني.","example":"احسب OR ← اعكس الناتج ← اكتب NOR","note":"غيّر القيم في المختبر ولاحظ الفرق بين النتيجة والتوقع."},{"title":"خطأ شائع وكيف تتجنبه","body":"لا تعتبر NOR مرادفة NAND؛ جرّب المدخلين 00 وستجد NAND=1 وNOR=1، لكن في 01 تختلفان. خطوات الحل: احسب OR ← اعكس الناتج ← اكتب NOR. تذكّر المصطلح أو الناتج: 0.","example":"مثال: 0","note":"الاختبار يقيس ناتج الدائرة، وليس حفظ اسمها فقط."}],"lab":{"kind":"gates","gate":"NOR"}},"questions":[{"number":0,"kind":"choice","prompt":"ما NOR(0,0)؟","target":"","options":["2","غير معرّف","1","0"],"answerIndex":2,"explanation":"NOR هي ناتج OR ثم نفيه: NOR(A,B)=NOT(OR(A,B)). تخرج 1 فقط عندما يكون كلا المدخلين 0، وتخرج 0 إذا دخلت قيمة 1 على أي منهما."},{"number":1,"kind":"choice","prompt":"ما NOR(1,0)؟","target":"","options":["غير معروف","0","1","2"],"answerIndex":1,"explanation":"إذا كان A=0 وB=0 فإن OR تساوي 0 وNOR تساوي 1. أما إذا A=1 فإن NOR تساوي 0 بصرف النظر عن المدخل الثاني."},{"number":2,"kind":"choice","prompt":"NOR تعادل ماذا؟","target":"","options":["NOT بعد OR","NOT بعد AND","AND وحدها","XOR"],"answerIndex":0,"explanation":"NOR هي ناتج OR ثم نفيه: NOR(A,B)=NOT(OR(A,B)). تخرج 1 فقط عندما يكون كلا المدخلين 0، وتخرج 0 إذا دخلت قيمة 1 على أي منهما."},{"number":3,"kind":"choice","prompt":"ما أول خطوة في تمرين «بوابة NOR: نفي OR»؟","target":"","options":["اعكس الناتج","اكتب NOR","اختر نتيجة عشوائية","احسب OR"],"answerIndex":3,"explanation":"NOR هي ناتج OR ثم نفيه: NOR(A,B)=NOT(OR(A,B)). تخرج 1 فقط عندما يكون كلا المدخلين 0، وتخرج 0 إذا دخلت قيمة 1 على أي منهما."},{"number":4,"kind":"order","prompt":"رتّب خطوات تمرين «بوابة NOR: نفي OR».","target":"","tokens":["اكتب NOR","اعكس الناتج","احسب OR"],"answer":["احسب OR","اعكس الناتج","اكتب NOR"],"explanation":"الترتيب الصحيح: احسب OR ← اعكس الناتج ← اكتب NOR."},{"number":5,"kind":"type","prompt":"ما ناتج NOR(1,1)؟","target":"","answer":"0","explanation":"NOR هي ناتج OR ثم نفيه: NOR(A,B)=NOT(OR(A,B)). تخرج 1 فقط عندما يكون كلا المدخلين 0، وتخرج 0 إذا دخلت قيمة 1 على أي منهما."}]},{"index":6,"stage":{"title":"بوابة XOR: الاختلاف","subtitle":"اختر المدخلات وشاهد النتيجة مباشرة","intro":"في هذه المحطة نتعلم بوابة XOR: الاختلاف بوساطة جدول الحقيقة والمحاكاة الحية. XOR أو «أو الحصرية» تعطي 1 حين تختلف قيمتا المدخلين، و0 إذا تساوتا. جدولها: 00→0، 01→1، 10→1، 11→0.","tips":["XOR أو «أو الحصرية» تعطي 1 حين تختلف قيمتا المدخلين، و0 إذا تساوتا. جدولها: 00→0، 01→1، 10→1، 11→0.","إذا اختار شخصان قرارين مختلفين فالناتج 1 في نموذج XOR. لكن إذا اتفقا على 0 أو 1 فالناتج 0؛ جرب كل الحالات في مختبر البوابات.","لا تخلط XOR مع OR الشاملة، لأن OR(1,1)=1 بينما XOR(1,1)=0. الاختلاف هو مفتاح هذه البوابة."],"lessons":[{"title":"كيف تعمل هذه البوابة؟","body":"XOR أو «أو الحصرية» تعطي 1 حين تختلف قيمتا المدخلين، و0 إذا تساوتا. جدولها: 00→0، 01→1، 10→1، 11→0.","example":"مثال: 0","note":"اقرأ المدخلات والناتج في جميع الحالات حتى تستوعب وظيفة البوابة."},{"title":"مثال محلول على الصفر والواحد","body":"إذا اختار شخصان قرارين مختلفين فالناتج 1 في نموذج XOR. لكن إذا اتفقا على 0 أو 1 فالناتج 0؛ جرب كل الحالات في مختبر البوابات.","example":"اقرأ المدخلين ← قارن القيم ← ضع 1 إن اختلفتا","note":"غيّر القيم في المختبر ولاحظ الفرق بين النتيجة والتوقع."},{"title":"خطأ شائع وكيف تتجنبه","body":"لا تخلط XOR مع OR الشاملة، لأن OR(1,1)=1 بينما XOR(1,1)=0. الاختلاف هو مفتاح هذه البوابة. خطوات الحل: اقرأ المدخلين ← قارن القيم ← ضع 1 إن اختلفتا. تذكّر المصطلح أو الناتج: 1.","example":"مثال: 1","note":"الاختبار يقيس ناتج الدائرة، وليس حفظ اسمها فقط."}],"lab":{"kind":"gates","gate":"XOR"}},"questions":[{"number":0,"kind":"choice","prompt":"ما XOR(1,1)؟","target":"","options":["غير معروف","0","1","2"],"answerIndex":1,"explanation":"XOR أو «أو الحصرية» تعطي 1 حين تختلف قيمتا المدخلين، و0 إذا تساوتا. جدولها: 00→0، 01→1، 10→1، 11→0."},{"number":1,"kind":"choice","prompt":"ما XOR(0,1)؟","target":"","options":["1","0","2","غير معرّف"],"answerIndex":0,"explanation":"إذا اختار شخصان قرارين مختلفين فالناتج 1 في نموذج XOR. لكن إذا اتفقا على 0 أو 1 فالناتج 0؛ جرب كل الحالات في مختبر البوابات."},{"number":2,"kind":"choice","prompt":"متى تكون XOR تساوي 1؟","target":"","options":["عندما تتساوى","عندما تكون الاثنتان 1","عندما تكون الاثنتان 0","عندما تختلف المدخلات"],"answerIndex":3,"explanation":"XOR أو «أو الحصرية» تعطي 1 حين تختلف قيمتا المدخلين، و0 إذا تساوتا. جدولها: 00→0، 01→1، 10→1، 11→0."},{"number":3,"kind":"choice","prompt":"ما أول خطوة في تمرين «بوابة XOR: الاختلاف»؟","target":"","options":["ضع 1 إن اختلفتا","اختر نتيجة عشوائية","اقرأ المدخلين","قارن القيم"],"answerIndex":2,"explanation":"XOR أو «أو الحصرية» تعطي 1 حين تختلف قيمتا المدخلين، و0 إذا تساوتا. جدولها: 00→0، 01→1، 10→1، 11→0."},{"number":4,"kind":"order","prompt":"رتّب خطوات تمرين «بوابة XOR: الاختلاف».","target":"","tokens":["ضع 1 إن اختلفتا","قارن القيم","اقرأ المدخلين"],"answer":["اقرأ المدخلين","قارن القيم","ضع 1 إن اختلفتا"],"explanation":"الترتيب الصحيح: اقرأ المدخلين ← قارن القيم ← ضع 1 إن اختلفتا."},{"number":5,"kind":"type","prompt":"ما ناتج XOR(1,0)؟","target":"","answer":"1","explanation":"XOR أو «أو الحصرية» تعطي 1 حين تختلف قيمتا المدخلين، و0 إذا تساوتا. جدولها: 00→0، 01→1، 10→1، 11→0."}]},{"index":7,"stage":{"title":"بوابة XNOR: التساوي","subtitle":"اختر المدخلات وشاهد النتيجة مباشرة","intro":"في هذه المحطة نتعلم بوابة XNOR: التساوي بوساطة جدول الحقيقة والمحاكاة الحية. XNOR هي نفي XOR وتُخرج 1 عندما تتساوى القيمتان: 00→1 و11→1، بينما 01 و10 تعطيان صفرًا. لذلك يمكن اعتبارها كاشف تساوٍ بسيطًا.","tips":["XNOR هي نفي XOR وتُخرج 1 عندما تتساوى القيمتان: 00→1 و11→1، بينما 01 و10 تعطيان صفرًا. لذلك يمكن اعتبارها كاشف تساوٍ بسيطًا.","إذا كان A=1 وB=1 فإن XOR=0 وXNOR=1. وإذا A=0 وB=1 فإن XOR=1 وXNOR=0. اعكس نتيجة XOR فقط.","لا تجعل XNOR بوابة تحقق الاختلاف؛ هذه وظيفة XOR. اكتب الجدول أمامك إن التبس عليك الاسمان."],"lessons":[{"title":"كيف تعمل هذه البوابة؟","body":"XNOR هي نفي XOR وتُخرج 1 عندما تتساوى القيمتان: 00→1 و11→1، بينما 01 و10 تعطيان صفرًا. لذلك يمكن اعتبارها كاشف تساوٍ بسيطًا.","example":"مثال: 1","note":"اقرأ المدخلات والناتج في جميع الحالات حتى تستوعب وظيفة البوابة."},{"title":"مثال محلول على الصفر والواحد","body":"إذا كان A=1 وB=1 فإن XOR=0 وXNOR=1. وإذا A=0 وB=1 فإن XOR=1 وXNOR=0. اعكس نتيجة XOR فقط.","example":"احسب XOR ← اعكس القيمة ← راجع التساوي","note":"غيّر القيم في المختبر ولاحظ الفرق ب