طي قيمًا مختلفة؛ ابدأ من المدخلات واتبع اتجاه تدفق الإشارة."],"lessons":[{"title":"كيف تعمل هذه البوابة؟","body":"يمكن وصل مخرج بوابة بمدخل أخرى لتكوين شرط مركّب. احسب الناتج الأول ثم طبّق البوابة الثانية؛ لا تجمع القاعدتين بالتخمين.","example":"مثال: 1","note":"اقرأ المدخلات والناتج في جميع الحالات حتى تستوعب وظيفة البوابة."},{"title":"مثال محلول على الصفر والواحد","body":"إذا طبّقت AND ثم NOT حصلت على NAND. مع A=1 وB=0 يكون AND=0 ثم NOT=1؛ أي NAND=1. يمكنك مقارنة النتيجة بجدول NAND مباشرة.","example":"احسب أول بوابة ← مرر الناتج ← طبق الثانية","note":"غيّر القيم في المختبر ولاحظ الفرق بين النتيجة والتوقع."},{"title":"خطأ شائع وكيف تتجنبه","body":"قد يكون للدوائر المركبة ترتيب عمليات واضح في الرسم. تجاهل الترتيب سيعطي قيمًا مختلفة؛ ابدأ من المدخلات واتبع اتجاه تدفق الإشارة. خطوات الحل: احسب أول بوابة ← مرر الناتج ← طبق الثانية. تذكّر المصطلح أو الناتج: 0.","example":"مثال: 0","note":"الاختبار يقيس ناتج الدائرة، وليس حفظ اسمها فقط."}],"lab":{"kind":"gates","gate":"NAND"}},"questions":[{"number":0,"kind":"choice","prompt":"ما ناتج NOT(AND(1,0))؟","target":"","options":["2","غير ممكن","1","0"],"answerIndex":2,"explanation":"يمكن وصل مخرج بوابة بمدخل أخرى لتكوين شرط مركّب. احسب الناتج الأول ثم طبّق البوابة الثانية؛ لا تجمع القاعدتين بالتخمين."},{"number":1,"kind":"choice","prompt":"ما اسم AND تتبعها NOT؟","target":"","options":["XOR","NAND","NOR","OR"],"answerIndex":1,"explanation":"إذا طبّقت AND ثم NOT حصلت على NAND. مع A=1 وB=0 يكون AND=0 ثم NOT=1؛ أي NAND=1. يمكنك مقارنة النتيجة بجدول NAND مباشرة."},{"number":2,"kind":"choice","prompt":"ما القاعدة الصحيحة لحساب الدارة؟","target":"","options":["احسب كل بوابة بالترتيب","ابدأ من المخرج عشوائيًا","اجمع المدخلين حسابيًا","تجاهل نوع البوابة"],"answerIndex":0,"explanation":"يمكن وصل مخرج بوابة بمدخل أخرى لتكوين شرط مركّب. احسب الناتج الأول ثم طبّق البوابة الثانية؛ لا تجمع القاعدتين بالتخمين."},{"number":3,"kind":"choice","prompt":"ما أول خطوة في تمرين «تركيب البوابات على مرحلتين»؟","target":"","options":["مرر الناتج","طبق الثانية","اختر نتيجة عشوائية","احسب أول بوابة"],"answerIndex":3,"explanation":"يمكن وصل مخرج بوابة بمدخل أخرى لتكوين شرط مركّب. احسب الناتج الأول ثم طبّق البوابة الثانية؛ لا تجمع القاعدتين بالتخمين."},{"number":4,"kind":"order","prompt":"رتّب خطوات تمرين «تركيب البوابات على مرحلتين».","target":"","tokens":["طبق الثانية","مرر الناتج","احسب أول بوابة"],"answer":["احسب أول بوابة","مرر الناتج","طبق الثانية"],"explanation":"الترتيب الصحيح: احسب أول بوابة ← مرر الناتج ← طبق الثانية."},{"number":5,"kind":"type","prompt":"ما ناتج NOT(AND(1,1))؟","target":"","answer":"0","explanation":"يمكن وصل مخرج بوابة بمدخل أخرى لتكوين شرط مركّب. احسب الناتج الأول ثم طبّق البوابة الثانية؛ لا تجمع القاعدتين بالتخمين."}]},{"index":10,"stage":{"title":"الجامع النصفي: جمع بت واحد","subtitle":"اختر المدخلات وشاهد النتيجة مباشرة","intro":"في هذه المحطة نتعلم الجامع النصفي: جمع بت واحد بوساطة جدول الحقيقة والمحاكاة الحية. الجامع النصفي دائرة بسيطة تجمع بتين دون حمل وارد: Sum = XOR(A,B) وCarry = AND(A,B). عند 1+1 تكون Sum=0 وCarry=1؛ ويمثل هذا 10 بالنظام الثنائي.","tips":["الجامع النصفي دائرة بسيطة تجمع بتين دون حمل وارد: Sum = XOR(A,B) وCarry = AND(A,B). عند 1+1 تكون Sum=0 وCarry=1؛ ويمثل هذا 10 بالنظام الثنائي.","عندما A=1 وB=0 ينتج Sum=1 وCarry=0. وعندما A=1 وB=1 تنتج Sum=0 وCarry=1. المختبر يعرض النتيجتين معًا.","الجامع النصفي ليس جامعًا كاملًا، لأنه لا يعالج حملًا واردًا من خانة سابقة؛ وفيه مخرجان لا مخرج واحد."],"lessons":[{"title":"كيف تعمل هذه البوابة؟","body":"الجامع النصفي دائرة بسيطة تجمع بتين دون حمل وارد: Sum = XOR(A,B) وCarry = AND(A,B). عند 1+1 تكون Sum=0 وCarry=1؛ ويمثل هذا 10 بالنظام الثنائي.","example":"XOR","note":"اقرأ المدخلات والناتج في جميع الحالات حتى تستوعب وظيفة البوابة."},{"title":"مثال محلول على الصفر والواحد","body":"عندما A=1 وB=0 ينتج Sum=1 وCarry=0. وعندما A=1 وB=1 تنتج Sum=0 وCarry=1. المختبر يعرض النتيجتين معًا.","example":"احسب XOR للـ Sum ← احسب AND للـ Carry ← اكتب الناتجين","note":"غيّر القيم في المختبر ولاحظ الفرق بين النتيجة والتوقع."},{"title":"خطأ شائع وكيف تتجنبه","body":"الجامع النصفي ليس جامعًا كاملًا، لأنه لا يعالج حملًا واردًا من خانة سابقة؛ وفيه مخرجان لا مخرج واحد. خطوات الحل: احسب XOR للـ Sum ← احسب AND للـ Carry ← اكتب الناتجين. تذكّر المصطلح أو الناتج: 1.","example":"مثال: 1","note":"الاختبار يقيس ناتج الدائرة، وليس حفظ اسمها فقط."}],"lab":{"kind":"gates","gate":"HALF_ADDER"}},"questions":[{"number":0,"kind":"choice","prompt":"ما البوابة التي تعطي Sum في الجامع النصفي؟","target":"","options":["NOR","XOR","AND","OR"],"answerIndex":1,"explanation":"الجامع النصفي دائرة بسيطة تجمع بتين دون حمل وارد: Sum = XOR(A,B) وCarry = AND(A,B). عند 1+1 تكون Sum=0 وCarry=1؛ ويمثل هذا 10 بالنظام الثنائي."},{"number":1,"kind":"choice","prompt":"ما البوابة التي تعطي Carry؟","target":"","options":["AND","XOR","NOT","BUFFER"],"answerIndex":0,"explanation":"عندما A=1 وB=0 ينتج Sum=1 وCarry=0. وعندما A=1 وB=1 تنتج Sum=0 وCarry=1. المختبر يعرض النتيجتين معًا."},{"number":2,"kind":"choice","prompt":"كم يساوي 1+1 في جامع نصفي (Sum,Carry)؟","target":"","options":["Sum=1, Carry=0","Sum=1, Carry=1","Sum=0, Carry=0","Sum=0, Carry=1"],"answerIndex":3,"explanation":"الجامع النصفي دائرة بسيطة تجمع بتين دون حمل وارد: Sum = XOR(A,B) وCarry = AND(A,B). عند 1+1 تكون Sum=0 وCarry=1؛ ويمثل هذا 10 بالنظام الثنائي."},{"number":3,"kind":"choice","prompt":"ما أول خطوة في تمرين «الجامع النصفي: جمع بت واحد»؟","target":"","options":["اكتب الناتجين","اختر نتيجة عشوائية","احسب XOR للـ Sum","احسب AND للـ Carry"],"answerIndex":2,"explanation":"الجامع النصفي دائرة بسيطة تجمع بتين دون حمل وارد: Sum = XOR(A,B) وCarry = AND(A,B). عند 1+1 تكون Sum=0 وCarry=1؛ ويمثل هذا 10 بالنظام الثنائي."},{"number":4,"kind":"order","prompt":"رتّب خطوات تمرين «الجامع النصفي: جمع بت واحد».","target":"","tokens":["اكتب الناتجين","احسب AND للـ Carry","احسب XOR للـ Sum"],"answer":["احسب XOR للـ Sum","احسب AND للـ Carry","اكتب الناتجين"],"explanation":"الترتيب الصحيح: احسب XOR للـ Sum ← احسب AND للـ Carry ← اكتب الناتجين."},{"number":5,"kind":"type","prompt":"ما Carry عند A=1 وB=1؟","target":"","answer":"1","explanation":"الجامع النصفي دائرة بسيطة تجمع بتين دون حمل وارد: Sum = XOR(A,B) وCarry = AND(A,B). عند 1+1 تكون Sum=0 وCarry=1؛ ويمثل هذا 10 بالنظام الثنائي."}]},{"index":11,"stage":{"title":"المشروع الأخير: تصميم دارة","subtitle":"اختر المدخلات وشاهد النتيجة مباشرة","intro":"في هذه المحطة نتعلم المشروع الأخير: تصميم دارة بوساطة جدول الحقيقة والمحاكاة الحية. لتصميم دارة من شرط لغوي، حدد المدخلات والمخرج، ثم اختر البوابة أو تركيب البوابات المناسب، ثم تحقق بجميع صفوف جدول الحقيقة. لا تعتمد على اسم البوابة فقط.","tips":["لتصميم دارة من شرط لغوي، حدد المدخلات والمخرج، ثم اختر البوابة أو تركيب البوابات المناسب، ثم تحقق بجميع صفوف جدول الحقيقة. لا تعتمد على اسم البوابة فقط.","شرط «يعمل الإنذار إذا فُتح أي باب» يناسب OR، وشرط «يعمل إذا فُتح البابان معًا» يناسب AND. أما اختلاف حالتي بابين فيناسب XOR.","في المشروع الأخير عليك تبرير الاختيار وتختبر 00 و01 و10 و11. الانتباه إلى «أي واحد» و«كلاهما» و«مختلفان» يمنع أخطاء تصميم النظام."],"lessons":[{"title":"كيف تعمل هذه البوابة؟","body":"لتصميم دارة من شرط لغوي، حدد المدخلات والمخرج، ثم اختر البوابة أو تركيب البوابات المناسب، ثم تحقق بجميع صفوف جدول الحقيقة. لا تعتمد على اسم البوابة فقط.","example":"OR","note":"اقرأ المدخلات والناتج في جميع الحالات حتى تستوعب وظيفة البوابة."},{"title":"مثال محلول على الصفر والواحد","body":"شرط «يعمل الإنذار إذا فُتح أي باب» يناسب OR، وشرط «يعمل إذا فُتح البابان معًا» يناسب AND. أما اختلاف حالتي بابين فيناسب XOR.","example":"حدد الشرط ← اختر البوابة ← اختبر جدول الحقيقة","note":"غيّر القيم في المختبر ولاحظ الفرق بين النتيجة والتوقع."},{"title":"خطأ شائع وكيف تتجنبه","body":"في المشروع الأخير عليك تبرير الاختيار وتختبر 00 و01 و10 و11. الانتباه إلى «أي واحد» و«كلاهما» و«مختلفان» يمنع أخطاء تصميم النظام. خطوات الحل: حدد الشرط ← اختر البوابة ← اختبر جدول الحقيقة. تذكّر المصطلح أو الناتج: XOR.","example":"XOR","note":"الاختبار يقيس ناتج الدائرة، وليس حفظ اسمها فقط."}],"lab":{"kind":"gates","gate":"XOR"}},"questions":[{"number":0,"kind":"choice","prompt":"ما بوابة «أي باب مف