insert into public.school_editor_courses(slug,draft,published,version,published_version,updated_by)
select c.item->>'slug',c.item->'course',c.item->'course',1,1,null
from pg_temp.school967_logic_seed t cross join lateral jsonb_array_elements(t.payload) c(item)
on conflict (slug) do nothing;

insert into public.school_editor_stages(course_slug,stage_index,draft,published,version,published_version,updated_by)
select c.item->>'slug',(s.item->>'index')::integer,s.item->'stage',s.item->'stage',1,1,null
from pg_temp.school967_logic_seed t
cross join lateral jsonb_array_elements(t.payload) c(item)
cross join lateral jsonb_array_elements(c.item->'stages') s(item)
on conflict (course_slug,stage_index) do nothing;

insert into public.school_editor_questions(id,course_slug,stage_index,draft,published,version,published_version,updated_by)
select md5('school-logic-967:v1:'||(c.item->>'slug')||':'||(s.item->>'index')||':'||(q.item->>'number'))::uuid,
 c.item->>'slug',(s.item->>'index')::integer,q.item-'number',q.item-'number',1,1,null
from pg_temp.school967_logic_seed t
cross join lateral jsonb_array_elements(t.payload) c(item)
cross join lateral jsonb_array_elements(c.item->'stages') s(item)
cross join lateral jsonb_array_elements(s.item->'questions') q(item)
on conflict (id) do nothing;
